test('applies functions left-to-right', () => {
  const double = x => x * 2;
  const addOne = x => x + 1;
  expect(pipe(double, addOne)(3)).toBe(7);
});

test('single function acts as identity wrapper', () => {
  const double = x => x * 2;
  expect(pipe(double)(5)).toBe(10);
});

test('pipes three functions', () => {
  const triple = x => x * 3;
  const addTwo = x => x + 2;
  const negate = x => -x;
  expect(pipe(triple, addTwo, negate)(4)).toBe(-14);
});

test('leftmost function receives the initial value', () => {
  const calls = [];
  const tag = name => x => { calls.push(name); return x; };
  pipe(tag('first'), tag('second'))(0);
  expect(calls).toEqual(['first', 'second']);
});

