  const upper = s => s.toUpperCase();
  expect(pipe(trim, upper)('  hello  ')).toBe('HELLO');
});

solution:
export function pipe(...fns) {
  return function(x) {
    return fns.reduce((acc, fn) => fn(acc), x);
  };
}
